param()
$ErrorActionPreference = 'Stop'

$resourceDirectory = Join-Path $PSScriptRoot '../src/WinMon/Resources'
[xml]$resources = Get-Content -LiteralPath (Join-Path $resourceDirectory 'Strings.resx') -Raw
$code = [System.Text.StringBuilder]::new()
[void]$code.AppendLine(@'
// <auto-generated by tools/Generate-StringResources.ps1 />
#nullable enable
namespace WinMon.Resources;

/// <summary>Text from Strings.resx. Add translations as Strings.&lt;culture&gt;.resx.</summary>
public static partial class Strings
{
    public static System.Resources.ResourceManager ResourceManager { get; } = new("WinMon.Resources.Strings", typeof(Strings).Assembly);

'@)
foreach ($entry in $resources.root.data | Sort-Object name) {
    $name = $entry.name
    if ($name -cnotmatch '^[A-Za-z_][A-Za-z0-9_]*$') { throw "Invalid resource identifier: $name" }
    [void]$code.AppendLine("    public static string $name => ResourceManager.GetString(nameof($name), Culture ?? System.Globalization.CultureInfo.CurrentUICulture)!;")
}
[void]$code.AppendLine('}')
[System.IO.File]::WriteAllText((Join-Path $resourceDirectory 'Strings.Designer.cs'), $code.ToString(), [System.Text.UTF8Encoding]::new($false))
